\label{def:RCF}


A real closed field $F$ is a real field such that
\begin{enumerate}
  \item for all $x$ in $F$, either $x$ or $-x$ is a square in $F$, and
  \item every odd-degree polynomial over $F$ has a root in $F$.
\end{enumerate}

\label{lem:RCF_ord_ax}



An ordered field is real closed if
\begin{enumerate}
  \item every non-negative element is a square, and
  \item every odd-degree polynomial over $F$ has a root in $F$.
\end{enumerate}

\label{thm:RCF_tfae}



Let $R$ be a field. TFAE:
\begin{enumerate}
  \item $R$ is real closed.
  \item $\bar{R}=R(i)$ (and $R(i)\neq R$).
  \item $R$ is real, but has no nontrivial real algebraic extensions.
\end{enumerate}

\label{thm:RCF_tfae_ord}



Let $R$ be an ordered field. TFAE:
\begin{enumerate}
  \item $R$ is real closed.
  \item $R$ is maximal with respect to ordered algebraic extensions.
  \item Polynomials over $R$ satisfy the intermediate value property.
\end{enumerate}
